package io.github.diodeme.ji.relay;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Synchronized reference store used by contract tests and ephemeral Relay deployments. */
public final class MemoryRelayMetadataStore implements RelayMetadataStore {
    private final Map<String, Device> devices = new LinkedHashMap<>();
    private final Map<String, Host> hosts = new LinkedHashMap<>();
    private final Map<String, Invitation> invitations = new LinkedHashMap<>();
    private final Map<String, Grant> grants = new LinkedHashMap<>();

    @Override public synchronized Optional<Device> device(String tenantId, String deviceId) {
        return Optional.ofNullable(devices.get(key(tenantId, deviceId)));
    }

    @Override public synchronized List<Device> devices(String tenantId) {
        var result = new ArrayList<Device>();
        devices.values().stream().filter(device -> device.tenantId().equals(tenantId)).forEach(result::add);
        return List.copyOf(result);
    }

    @Override public synchronized void saveDevice(Device device) {
        Device existing = devices.get(key(device.tenantId(), device.deviceId()));
        if (existing != null && !java.security.MessageDigest.isEqual(existing.publicKey(), device.publicKey())) {
            throw new IllegalArgumentException("device identity changed");
        }
        devices.put(key(device.tenantId(), device.deviceId()), device);
    }

    @Override public synchronized void revokeDevice(String tenantId, String deviceId, Instant revokedAt) {
        Device existing = device(tenantId, deviceId).orElse(null);
        if (existing == null || existing.revokedAt().isPresent()) return;
        devices.put(key(tenantId, deviceId), new Device(existing.tenantId(), existing.deviceId(),
                existing.publicKey(), existing.roles(), existing.createdAt(), Optional.of(revokedAt)));
    }

    @Override public synchronized Optional<Host> host(String tenantId, String hostId) {
        return Optional.ofNullable(hosts.get(key(tenantId, hostId)));
    }

    @Override public synchronized void saveHost(Host host) {
        Host existing = hosts.get(key(host.tenantId(), host.hostId()));
        if (existing != null && !java.security.MessageDigest.isEqual(existing.publicKey(), host.publicKey())) {
            throw new IllegalArgumentException("Host identity changed");
        }
        hosts.put(key(host.tenantId(), host.hostId()), host);
    }

    @Override public synchronized Optional<Invitation> invitation(String tenantId, String invitationId) {
        return Optional.ofNullable(invitations.get(key(tenantId, invitationId)));
    }

    @Override public synchronized void saveInvitation(Invitation invitation) {
        if (invitations.putIfAbsent(key(invitation.tenantId(), invitation.invitationId()), invitation) != null) {
            throw new IllegalStateException("invitation already exists");
        }
    }

    @Override public synchronized boolean confirmInvitation(
            String tenantId, String invitationId, String confirmingDeviceId, Instant confirmedAt) {
        Invitation value = invitation(tenantId, invitationId).orElse(null);
        if (value == null || value.consumedAt().isPresent() || value.confirmedAt().isPresent()
                || !value.issuerDeviceId().equals(confirmingDeviceId) || !confirmedAt.isBefore(value.expiresAt())) {
            return false;
        }
        invitations.put(key(tenantId, invitationId), new Invitation(value.tenantId(), value.invitationId(),
                value.issuerDeviceId(), value.hostIds(), value.secretHash(), value.fingerprint(), value.expiresAt(),
                Optional.of(confirmedAt), Optional.empty()));
        return true;
    }

    @Override public synchronized boolean consumeInvitation(
            String tenantId, String invitationId, String deviceId, byte[] publicKey, Instant consumedAt) {
        Invitation value = invitation(tenantId, invitationId).orElse(null);
        if (value == null || value.confirmedAt().isEmpty() || value.consumedAt().isPresent()
                || !consumedAt.isBefore(value.expiresAt())) return false;
        invitations.put(key(tenantId, invitationId), new Invitation(value.tenantId(), value.invitationId(),
                value.issuerDeviceId(), value.hostIds(), value.secretHash(), value.fingerprint(), value.expiresAt(),
                value.confirmedAt(), Optional.of(consumedAt)));
        return true;
    }

    @Override public synchronized Optional<Grant> grant(String tenantId, String hostId, String deviceId) {
        return Optional.ofNullable(grants.get(grantKey(tenantId, hostId, deviceId)));
    }

    @Override public synchronized void saveGrant(Grant grant) {
        grants.put(grantKey(grant.tenantId(), grant.hostId(), grant.deviceId()), grant);
    }

    private static String key(String tenantId, String id) { return tenantId + '\0' + id; }
    private static String grantKey(String tenantId, String hostId, String deviceId) {
        return tenantId + '\0' + hostId + '\0' + deviceId;
    }
}
